```js
export default {
  root: "D:/projexts/moe-next/apps/daemon",
  test: { include: ["src/orchestrator/repository-delivery-runtime.test.ts"], maxWorkers: 1, testNamePattern: "keeps a refusal that already journaled an intent", passWithNoTests: false },
  plugins: [{ name: "governor-noeffect-observation", enforce: "pre", transform(code, id) {
    if (!id.replaceAll("\\", "/").endsWith("/repository-delivery-runtime.test.ts")) return;
    const anchor = 'expect(readRepositoryDeliveryFacts(f.store, f.projectId, "a", held.handle)).toBe("REFUSED");';
    if (code.split(anchor).length !== 2) throw new Error("PROBE_ANCHOR_COUNT_MISMATCH");
    code = code.replace('import { landingAggregateId }', 'import { landingAggregateId, landedWithNoEffect }');
    code = code.replace('import { readReviewLedger }', 'import { readReviewLedger, readReviewLedgers }');
    return { code: code.replace(anchor, anchor + `
      const probeReceipt = readReviewLedgers(f.store, f.projectId, new Set(["a"])).landings.get("a");
      expect(probeReceipt?.refusal?.code).toBe("NOTHING_TO_COMMIT");
      expect(probeReceipt, "EXPECTED_RUNTIME_LANDING_RECEIPT").toBeDefined();
      console.log("GOVERNOR_POST_INTENT_OBSERVATION", JSON.stringify({ outcome: probeReceipt!.outcome, code: probeReceipt!.refusal!.code, deliveryFacts: readRepositoryDeliveryFacts(f.store, f.projectId, "a", held.handle), credited: landedWithNoEffect(probeReceipt!) }));
      expect(landedWithNoEffect(probeReceipt!), "POST_INTENT_REFUSAL_MUST_NOT_BE_CREDITED").toBe(false);
    `), map: null };
  } }]
};
```

